const VERDICT = {clear:["pass","No violations: No MR."], comm:["pass","Comm moves clear every check: Com Rearrangement."], partial:["tbd","Comm moves leave sheet checks failing: see below."], power:["fail","Needs power make-ready, a midspan pole or a replacement."]};
