    let j; while((j = buf.indexOf("</Placemark>")) >= 0){ const s = buf.slice(0, j), i = s.lastIndexOf("<Placemark"); if(i>=0) routePlacemark(s.slice(i), kind, box, out); buf = buf.slice(j+12); }
