/* ---------- the after JSON: re-check every pole after the Katapult make-ready ---------- */
let JOB_AFTER = null;
function loadAfterText(text, name){
  let j; try{ j = JSON.parse(text); }catch(e){ toast("That file isn't valid JSON."); return; }
  if(!j || !j.nodes || !j.connections){ toast("That JSON doesn't look like a Katapult job export."); return; }
  if(!JOB){ toast("Load the before (existing) Job JSON first, then the after JSON."); return; }
  JOB_AFTER = j;
  const out = [], fresh = new Set(); let n = 0, miss = 0;
  for(let ci=0; ci<COLS.length;){
    const c = COLS[ci];
    if(!(c.node || c.tag)){ out.push(c); ci++; continue; }
    const g = groupOf(ci);
    out.push(...COLS.slice(g.start, g.start+g.n).filter(x=>!x.after));
    if(g.base.node && j.nodes[g.base.node]){ const a = afterCol(g.det, j); fresh.add(a); out.push(a); n++; }
    else { if(g.after) out.push(g.after); if(g.base.node) miss++; }
    ci = g.start + g.n;
  }
  COLS = out; SEL = Math.min(SEL, COLS.length-1);
  let clear = 0; groupStarts().forEach(s=>{ const g = groupOf(s); try{ if(g.after && fresh.has(g.after) && !violations(s, true).list.length) clear++; }catch(e){ console.error(e); } }); S = COLS[SEL];   /* only the poles this load re-checked (an older after column kept for a pole missing from this file isn't counted) */
  $("job-name").textContent = `${JOB.name||"Job"} · ${POLES.length} poles · after: ${name||j.name||"loaded"}`;
  render(); store.save(); setView("summary");
  toast(`After JSON: ${n} pole${n===1?"":"s"} re-checked, ${clear} clear, ${n-clear} still open${miss?`, ${miss} not in the after file`:""}.`);
}
$("a-file").addEventListener("change", e=>{ const f = e.target.files?.[0]; e.target.value = ""; if(!f) return; const rd = new FileReader(); rd.onload = ()=>loadAfterText(rd.result, f.name); rd.readAsText(f); });

