    let maxP = pr.length ? Math.min(...pr.map(r=>r.max)) : null, minPG = -Infinity, wP = "lowest power less the table spacing";
    // and at midspan: 12" / 30" / 60" under the power, 4" over... and its own ground clearance (it moves by its photo's share)
    let ph0 = parseFt(S.prop.height); if((ph0==null || isNaN(ph0)) && S.prop.trace && PL){ const w = PL.pw[S.prop.trace]; if(w && w.h!=null) ph0 = w.h; }
    if(maxP!=null && ph0!=null && !isNaN(ph0)) S.active.forEach(k=>{ const ps = S.prop.spans[k]; if(!ps?.in) return; const qm = parseFt(ps.mid), pm = parseFt(S.spans[k].mid), sh = SHv(ps.share); if(qm==null || isNaN(qm)) return;
      const r = calcProp(k); if(r.gcReq!=null){ const m = ph0 + (r.gcReq - qm)/sh; if(m > minPG) minPG = Math.ceil(m); } });
    if(maxP==null && PL && PL.low!=null && (parseFt(S.prop.height)!=null || (S.prop.trace && PL.pw[S.prop.trace]))){ maxP = PL.low - 44; wP = `44" below the lowest secondary/neutral bolt`; }   // on the pole but in no checked span
