/* ---------- ground elevation (USGS 3DEP point query) → elevation credit ---------- */
const ELEV = (()=>{ try{ return JSON.parse(localStorage.getItem("vcw-elev")||"{}"); }catch(e){ return {}; } })();
async function groundFt(lat, lon){
  const key = `${lat.toFixed(6)},${lon.toFixed(6)}`; if(ELEV[key]!=null) return ELEV[key];
  const ctl = new AbortController(), tm = setTimeout(()=>ctl.abort(), 9000);
  try{
    const r = await fetch(`https://epqs.nationalmap.gov/v1/json?x=${lon}&y=${lat}&wkid=4326&units=Feet&includeDate=false`, {signal:ctl.signal});
    const j = await r.json(); const v = parseFloat(j?.value);
    if(!isFinite(v) || v < -1000) throw new Error("no value");
    ELEV[key] = v; try{ localStorage.setItem("vcw-elev", JSON.stringify(ELEV)); }catch(e){}
    return v;
  } finally { clearTimeout(tm); }
}
function midPoint(sp){
  const conn = sp?.cid ? JOB.connections[sp.cid] : null; if(!conn) return null;
  const secs = Object.values(conn.sections||{}).filter(s=>isFinite(s.latitude) && isFinite(s.longitude));
  if(!secs.length) return null;
  // the section whose photos show the lowest wire is the low point Katapult measured
  let best = secs[0], low = Infinity;
  secs.forEach(s=>Object.keys(s.photos||{}).forEach(pid=>Object.values(JOB.photos?.[pid]?.photofirst_data?.wire||{}).forEach(w=>{ if(typeof w?._measured_height==="number" && w._measured_height<low){ low = w._measured_height; best = s; } })));
  return best;
}
async function checkElevation(cols){
  let done = 0, credits = 0, failed = 0;
  for(const c of cols){   // column objects, not positions: columns can be added, removed or rebuilt while the lookups are in flight
    if(!c || !COLS.includes(c)) continue;
    const n = JOB?.nodes?.[c.node]; if(!n) continue;
    for(const k of KEYS){
      const sp = c.spans[k]; if(!String(sp.len||"").trim() || sp.elevSrc==="typed") continue;
      const m = midPoint(sp); if(!m || sp.olat==null) continue;
      try{
        const [gA, gB, gM] = await Promise.all([groundFt(n.latitude, n.longitude), groundFt(sp.olat, sp.olon), groundFt(m.latitude, m.longitude)]);
        const d = Math.min(gA, gB) - gM;
        sp.elevInfo = `Ground: this pole ${gA.toFixed(1)}′, other pole ${gB.toFixed(1)}′, midspan ${gM.toFixed(1)}′ (USGS 3DEP)`;
        if(d > 0.25){ sp.elev = fmt(d*12); sp.elevSrc = "usgs"; credits++; } else { sp.elev = ""; sp.elevSrc = "usgs"; }
        done++;
      }catch(e){ failed++; }
    }
    // keep the Pre-1990 copy / After MR column of the same pole in step
    const ci = COLS.indexOf(c); if(ci<0) continue;   // the column went away while its lookups ran
    const g = groupOf(ci); for(let i=g.start;i<g.start+g.n;i++) if(i!==ci) KEYS.forEach(k=>{ if(COLS[i].spans[k].elevSrc!=="typed"){ COLS[i].spans[k].elev = c.spans[k].elev; COLS[i].spans[k].elevSrc = c.spans[k].elevSrc; COLS[i].spans[k].elevInfo = c.spans[k].elevInfo; } });
    // with the credit, does the pole now pass Post-1990? then the Pre-1990 copy isn't needed (Workflow 411 step 7)
    if(c.pair){ const keep = c.over[3]; c.over[3] = "Post-1990"; eraFor(c); const still = anyFail(); if(!still){ for(let i=g.start+g.n-1;i>g.start;i--) if(COLS[i].twin) COLS.splice(i,1); c.pair = false; delete c.over[3]; c.warn = (c.warn||[]).concat([`Passes Post-1990 with the elevation credit, so the Pre-1990 copy was removed.`]); } else c.over[3] = keep; S = COLS[SEL]; }
  }
  render(); store.save();
  if(failed && !done) toast("Couldn't reach the USGS elevation service from here. Use Katapult's elevation tool and type the credit into the Elevation credit rows (page-only rows at the bottom of the sheet).");
  else toast(`Elevation checked on ${done} span${done===1?"":"s"}: ${credits} with lower ground at midspan${failed?` (${failed} couldn't be looked up)`:""}.`);
}
