/* ===================== Tracer pre-work & overlap watch list ===================== */
// Flags poles where someone already did make-ready, wrote design notes, or that overlap another proposal.
function pwAttr(n, k){ const a = n?.attributes?.[k]; if(a==null) return ""; if(typeof a!=="object") return String(a); return [...new Set(Object.values(a).filter(x=>x!=null && typeof x!=="object" && String(x).trim()!=="").map(x=>String(x).trim()))].join("\n"); }
const pwToks = s => String(s||"").toLowerCase().match(/[a-z]+|\d+/g)?.map(t=>/^\d+$/.test(t)?String(+t):t).sort().join(" ") || "";
function pwWalk(o, acc){
  if(!o || typeof o!=="object") return;
  if(Object.prototype.hasOwnProperty.call(o, "mr_move")){ const v = parseFloat(o.mr_move); if(isFinite(v) && v!==0) acc.moves++; }
  if(typeof o.mr_note==="string" && o.mr_note.trim()) acc.notes.push(o.mr_note.trim());
  for(const k in o) if(k!=="mr_move" && k!=="mr_note" && o[k] && typeof o[k]==="object") pwWalk(o[k], acc);
}
function pwScan(job){
  if(!job?.nodes) return [];
  const out = [];
  const photosOf = n => Object.keys(n?.photos||{});
  const conns = Object.entries(job.connections||{});
  POLES.forEach(p=>{
    const n = job.nodes[p.id]; if(!n) return;
    const pole = {moves:0, notes:[]}, mid = {moves:0, notes:[]};
    photosOf(n).forEach(id=>pwWalk(job.photos?.[id]?.photofirst_data, pole));
    conns.forEach(([,c])=>{ if(c.node_id_1!==p.id && c.node_id_2!==p.id) return;
      Object.values(c.sections||{}).forEach(s=>Object.keys(s.photos||{}).forEach(id=>pwWalk(job.photos?.[id]?.photofirst_data, mid))); });
    const mre = pwAttr(n,"MRE_NOTE"), remedy = pwAttr(n,"remedy_notes"), outc = pwAttr(n,"MR_OUTCOME"), pmr = pwAttr(n,"POWER_MRE_REQUIRED");
    const txt = [pwAttr(n,"note"), pwAttr(n,"internal_note"), remedy, mre].join(" · ");
    const ol = txt.match(/Overlap:\s*([^\n·]*)/i);
    const overlap = (ol ? !/^\s*(no\b|none|n\/a|na\b)/i.test(ol[1]) && ol[1].trim()!=="" : /overlap|adjacent proposal|other proposal|another proposal/i.test(txt.replace(/no overlap( present)?/ig,""))) || /OVERLAP/i.test(outc);
    const cp = (pwAttr(n,"internal_note")+"\n"+pwAttr(n,"note")).match(/Node copied from ([^\n]+)/i);
    const jt = new Set(pwToks(job.name||"").split(" ")), copied = cp && !pwToks(cp[1].trim()).split(" ").every(t=>jt.has(t)) ? cp[1].trim() : "";  // copied from the parent/master job is normal; another proposal isn't
    const ref = /\.[A-Z]$/i.test(String(p.scid||""));
    const flags = [];
    if(pole.moves || pole.notes.length) flags.push({lvl:"hi", t:`MR already in Katapult: ${pole.moves} move${pole.moves===1?"":"s"} on the pole photo${pole.notes.length?` + note "${pole.notes.join("; ")}"`:""}`});
    if(mid.moves) flags.push({lvl:"hi", t:`MR already on its midspans: ${mid.moves} move${mid.moves===1?"":"s"}`});
    if(remedy) flags.push({lvl:"hi", t:`Remedy notes already written: "${remedy.slice(0,120)}${remedy.length>120?"…":""}"`});
    if(outc) flags.push({lvl:/OVERLAP/i.test(outc)?"hi":"lo", t:`MR OUTCOME already set: ${outc}`});
    if(pmr) flags.push({lvl:"lo", t:`Power MRE Required already set: ${pmr}`});
    if(overlap && !ol) flags.push({lvl:"hi", t:"Overlapping / adjacent proposal mentioned in its notes"});
    if(copied) flags.push({lvl:"hi", t:`Copied in from another job: ${copied}. Its make-ready and notes belong to that job`});
    if(ol && overlap) flags.push({lvl:"hi", t:`Tracer note says Overlap: ${ol[1].trim()}`});
    if(ref) flags.push({lvl:"mid", t:`SCID ${p.scid}: a lettered SCID is usually a reference or adjacent pole; check which proposal it belongs to`});
    if(mre) flags.push({lvl:"lo", t:`MRE NOTE field: "${mre.split(/\n/)[0].slice(0,90)}${mre.length>90?"…":""}" (applicant or tracer text, not your design)`});
    if(flags.some(f=>f.lvl!=="lo")) out.push({p, flags});
  });
  return out;
}
let PW_LIST = [];
function pwRefresh(){ try{ PW_LIST = JOB ? pwScan(JOB) : []; }catch(e){ console.error(e); PW_LIST = []; } }
function pwHTML(){
  if(!PW_LIST.length) return "";
  const rows = PW_LIST.map(({p,flags})=>{ const ci = COLS.findIndex(c=>c.node===p.id && !c.twin && !c.after);
    return `<tr><td><b>${esc(p.scid)}</b>${ci>=0?`<br><button type="button" class="cell-link" data-jumpcol="${ci}">column ${letterOf(ci)}</button>`:""}</td><td>${esc(p.tag||"")}</td><td><ul class="pw-f">${flags.map(f=>`<li class="pw-${f.lvl}">${esc(f.t)}</li>`).join("")}</ul></td></tr>`; }).join("");
  return `<div class="pw-box" id="pw-box"><h3>⚠ Before you start: ${PW_LIST.length} pole${PW_LIST.length>1?"s":""} to watch</h3>
   <p class="muted" style="margin:0 0 6px">Someone already worked these poles in Katapult, or they overlap another proposal. Their make-ready is <b>not yours yet</b>: the existing columns here ignore MR moves, but Katapult's MR view, the After MR column and your PLA will include them.</p>
   <table class="pw-t"><thead><tr><th>SCID</th><th>Pole tag</th><th>What's already there</th></tr></thead><tbody>${rows}</tbody></table>
   <details class="pw-how"><summary>What to do with them</summary><ol>
    <li><b>Overlapping / adjacent pole:</b> look the tag up in SPANS and the Master Tracker first. If the other proposal is past final review (permitting), use its design; don't redo or reset it. Note it in your Notes row and ask your lead how to annotate the overlap.</li>
    <li><b>MR already in Katapult:</b> compare each move with the photos and your own fix. If it's right, keep it and own it. If it's wrong or you're redoing the pole, in Katapult's make-ready panel use <b>Alternate Designs → save</b> the current design first (so the tracer's calls aren't lost), then <b>reset</b> the make-ready calls and do your own.</li>
    <li><b>Remedy / MR outcome / MRE notes already filled:</b> they're not the team's wording. Replace them with your own annotation note; don't copy them.</li>
    <li><b>Tracing looks wrong</b> (heights, wire specs, missed wires)? Fix the trace before you fill the sheet, then re-export the Job JSON and load it again. Ask your lead before deleting a tracer's work on a pole someone else owns.</li>
   </ol></details></div>`;
}
