function redHTML(){
  const gs = groupStarts(); if(!gs.length) return "";
  const yes = gs.filter(s=>COLS[s].red==="Y").map(s=>POLES.find(p=>p.id===COLS[s].node)?.scid || COLS[s].tag);
  const unset = gs.filter(s=>!COLS[s].red).length;
  return `<div class="help" style="margin:0 0 12px"><b>Row 7 · Red tag.</b> Katapult has no red-tag field, so check the pole photos. ${yes.length?`Marked <b>Yes</b>: SCID ${yes.map(esc).join(", ")}. `:""}${unset?`${unset} pole${unset>1?"s":""} not set yet. Once you've checked the photos: <button type="button" id="btn-redno">Mark the ${unset} unset pole${unset>1?"s":""} No</button>`:"Every pole is set."}</div>`;
}
document.addEventListener("click", e=>{ if(e.target.id!=="btn-redno") return; const gs = groupStarts(); let n=0; gs.forEach(s=>{ const g = groupOf(s); if(!g.base.red){ COLS.slice(g.start, g.start+g.n).forEach(c=>{ if(!c.red) c.red = "N"; }); n++; } }); S = COLS[SEL]; render(); store.save(); renderTabView(); toast(`Row 7 set to No on ${n} pole${n===1?"":"s"}.`); });
const pwWatch = c => !!(c && c.node && PW_LIST.some(x=>x.p.id===c.node));
function setView(v){
  VIEW = TABS.some(t=>t[0]===v) ? v : "template"; renderTabs();
  const t = VIEW==="template";
  $("wrap").hidden = !t; $("notes").hidden = !t; $("status").hidden = !t; $("tabview").hidden = t;
  if(!t) renderTabView();
}
const NESC_COLS = ["Post-1990 Neutral/Comm","Pre-1990 Neutral/Comm","Pre-1990 < 750 V","Pre-1990 < 22 kV LG","Pre-1961 Neutral/Comm","Pre-1961 < 750 V","Pre-1961 < 15 kV"];
function lookupHTML(title, sub, head, rows){
  const n = head.length;
  return `<h2>${esc(title)}</h2><p class="sub">${esc(sub)}</p><div class="lk-wrap"><table class="lk"><thead><tr><th class="rn"></th>${Array.from({length:n},(_,i)=>`<th>${colName(i+1)}</th>`).join("")}</tr></thead><tbody>
    <tr class="h"><td class="rn">1</td>${head.map(h=>`<td>${esc(h)}</td>`).join("")}</tr>
    ${rows.map((r,i)=>`<tr><td class="rn">${i+2}</td>${r.map((v,j)=>`<td class="${j===0?"l":""}${v==="TBD"?" tbd":""}">${esc(v)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
}
function tableTab(key, title, sub){
  const t = DATA[key]; if(!t) return `<p class="muted">Table not found.</p>`;
  return lookupHTML(title, sub, ["Span (ft)", ...t.cols], t.rows.map(r=>[String(r[0]), ...r.slice(1).map(v=>v==null ? "TBD" : tblFmt(t, v))]));
}
/* Manual walkthrough steps fold open/closed; "Copy the templates and open Katapult" starts closed so the pole steps come first. The choice is remembered. */
let MW_OPEN = (()=>{ try{ return JSON.parse(localStorage.getItem("vcw-mw-open")||"{}"); }catch(e){ return {}; } })();
function mwCollapse(root){
  root.querySelectorAll(".mw-steps > li").forEach(li=>{
    const h = li.querySelector(":scope > h3"); if(!h) return;
    const title = h.textContent.trim(), d = document.createElement("details"), s = document.createElement("summary");
    d.className = "mw-step"; d.open = title in MW_OPEN ? MW_OPEN[title] : !/^Copy the templates/i.test(title);
    s.appendChild(h); d.appendChild(s); while(li.firstChild) d.appendChild(li.firstChild); li.appendChild(d);
    d.addEventListener("toggle", ()=>{ MW_OPEN[title] = d.open; try{ localStorage.setItem("vcw-mw-open", JSON.stringify(MW_OPEN)); }catch(e){} });
  });
}
function renderTabView(){
  const el = $("tabview");
  if(VIEW==="summary"){ el.innerHTML = pwHTML() + redHTML() + summaryHTML(); return; }
  if(VIEW==="manual"){ el.innerHTML = manualHTML(); mwCollapse(el); return; }
  if(VIEW==="fe"){ el.innerHTML = lookupHTML("FE Ground Clearances", "FirstEnergy / Mon Power ground clearances the Post-1990 checks use: lowest power by wire type, comms by the Comm column. N/A in a CS 03-016 row uses the road value. Pre-1990 uses the NESC Clearances tab.", ["Environment", ...FE_COLS.map(c=>FE_COL_LABEL[c])], Object.values(FE).map(f=>[f.label, ...f.v.map(x=>x==null?"N/A":fmt(x))])); return; }
  if(VIEW==="nesc"){ el.innerHTML = lookupHTML("NESC Clearances", "NESC Table 232-1 ground clearances the sheet uses (rows 45–50).", ["Environment", ...NESC_COLS], Object.entries(DATA.nesc).map(([k,v])=>[ENV_LABEL[k]||k, ...v.map(x=>x==null?"":fmt(x))])); return; }
  const M = {pre:["Pre-1990 Spacing","Pre-1990 Spacing","Neutral-to-comm separation at the pole on Pre-1990 lines (rows 120–125). TBD = past the table: midspan pole."],
    sag:["Secondary Neutral Sag","Secondary Neutral Sag","Secondary/neutral sag by span (rows 69–74). TBD = past the table: midspan pole."],
    cu:["Secondary Neutral-to-Copper Communications","Sec Neutral-to-Copper Comms","Post-1990 separation, secondary/neutral to copper (Telco)."],
    fo:["Secondary Neutral-to-Fiber Communications","Sec Neutral-to-Fiber Comms","Post-1990 separation, secondary/neutral to fiber (CATV / Fiber)."],
    ad:["Secondary Neutral-to-Foreign-Owned-ADSS","Sec Neutral-to-Foreign-Owned-ADSS","Post-1990 separation, secondary/neutral to ADSS (comm drops)."]}[VIEW];
  el.innerHTML = M ? tableTab(M[0], M[1], M[2]) : "";
}
function summaryHTML(){
  const gs = groupStarts(), s0 = SEL;
  const help = `<div class="help" id="help"><h3>How this sheet works</h3><ol>
    <li><b>Clean up the job in Katapult first</b>: pole markers on the pole shadows, down guys aligned, traces checked on every pole. The tool only reads what Katapult has.</li>
    <li><b>Load Job JSON</b> (Katapult Download Manager → Data → Job JSON). Each pole gets a column with the worksheet's rows; existing violations get a red corner (Fail). Post-1990 is checked first; if it fails on a pre-1990 line, row 3 switches to Pre-1990 (you can switch it back). A pole being replaced also gets a <b>SCID MR</b> column with the new pole.</li>
    <li>Verify each span's environment in the yellow STOP bar (WV Property Viewer). State and county routes are set to DOT Road automatically from the built-in WVDOH route data; Route / rail KMZ adds railroads or newer route files.</li>
    <li>The panel on the right lists the existing violations, then <b>How to fix</b>: which cell fails, the smallest comm move that clears every span (and the room each comm has on the pole), or why it needs power make-ready, a midspan pole or a replacement. <b>Apply fix plan</b> previews it in an After MR column.</li>
    <li>Make the moves in Katapult MR View, export the Job JSON again and use <b>Load after JSON</b>. Every pole gets an After MR column built from the after file; this tab shows which poles clear.</li>
    <li><b>Copy column</b> pastes the existing column into your worksheet (formula rows paste as the sheet's formulas). <b>Copy Notes row</b> / <b>Copy Notes rows</b> paste into the Notes worksheet (A8 for SCID 1).</li>
  </ol><ul>
    <li>Existing measured heights are locked so the existing-violation record can't be typed over. <b>Unlock existing heights</b> only to correct bad Katapult data.</li>
    <li>Comm moves: a move at one pole moves the midspan about half as much. An After MR column keeps Pre-1990 clearances unless the pole height changes (replacement → Post-1990).</li>
    <li>Comm drops load as their own ADSS row per company, like Telco loads as Copper; a company's drops aren't checked against its own strand.</li>
    <li>Comm-to-comm checks (12" at the pole, 6" same company, 4" midspan) and midspan comm-to-power (12"/30"/60") aren't rows in the worksheet; they show as EPC/EBC in the panel.</li></ul></div>`;
  if(!gs.length) return `<h2>Summary</h2><p class="sub">Load the Katapult Job JSON to see every pole here.</p>${help}`;
  let nV = 0, nA = 0, nClear = 0; const MT = {};
  const rows = gs.map(s=>{
    const V = violations(s), g = V.g, P = fixPlan(s), scid = POLES.find(p=>p.id===g.base.node)?.scid || g.base.tag || "";
    if(V.list.length) nV++;
    let aft = `<span class="muted">—</span>`;
    if(g.after){ nA++; const A = violations(s, true); if(!A.list.length) nClear++; aft = A.list.length ? `<span class="pill fail">${A.list.length} open</span> <span class="muted">${esc(afterLabel(g))}</span>` : `<span class="pill pass">Clear</span> <span class="muted">${esc(afterLabel(g))}</span>`; }
    const mt = mreTypeSuggest(V, P); MT[mt] = (MT[mt]||0) + 1;
    const codes = V.list.map(v=>`<span class="code ${v.code}" title="${esc((v.power?"MP power":v.who)+": "+(v.note||""))}">${v.code}</span>`).join("");
    const fixes = P.filter(f=>f.code!=="INFO").map(f=>`<li>${esc(f.katapult ? f.katapult.replace(/^Katapult MR View: /,"") : f.text.split(/(?<=\.)\s/)[0])}</li>`).join("");
    return `<tr><td class="scid"><button type="button" data-jumpcol="${s}">${esc(scid)}</button></td><td>${esc(g.base.tag||"")}</td><td>${esc(V.era)}</td><td>${codes||'<span class="pill pass">None</span>'}</td><td>${fixes?`<ul>${fixes}</ul>`:'<span class="muted">—</span>'}</td><td>${esc(mt)}</td><td>${aft}</td></tr>`;
  });
  SEL = s0; S = COLS[SEL];
  return `<h2>Summary</h2><p class="sub">${esc(JOB?.name||"")} · every pole loaded on the Template, its existing violations, the fix, and the after-JSON result. Click a SCID to open its column.</p>
    <div class="counters2"><div><b>${gs.length}</b><span>poles</span></div><div><b>${nV}</b><span>with existing violations</span></div><div><b>${nA}</b><span>re-checked after MR</span></div><div><b>${nClear}</b><span>clear after MR</span></div>${MTYPES.map(m=>`<div><b>${MT[m]||0}</b><span>${esc(m)}</span></div>`).join("")}</div>
    <table class="sum"><thead><tr><th>SCID</th><th>Pole tag</th><th>Row 3</th><th>Existing violations</th><th>Fix</th><th>MRE type</th><th>After MR</th></tr></thead><tbody>${rows.join("")}</tbody></table>${help}`;
}
$("btn-help").onclick = ()=>{ setView("summary"); $("help")?.scrollIntoView({block:"start"}); };
$("btn-save").onclick = ()=>{ const name = (JOB?.name || COLS.find(c=>c.proposal)?.proposal || "VDS") + " session.json";
  const d = {vdsSession:1, layout:2, saved:new Date().toISOString(), job:JOB?.name||"", cols:COLS, sel:SEL, start:$("start-col").value, wf:WF};
  offerFile(new TextEncoder().encode(JSON.stringify(d)), name.replace(/[\\/:*?"<>|]+/g," "), "Session saved. Open session brings it back; load the Job JSON too for the SCID pickers and after JSON."); };
$("s-file").addEventListener("change", e=>{ const f = e.target.files?.[0]; e.target.value = ""; if(!f) return; const rd = new FileReader();
  rd.onload = ()=>{ let d; try{ d = JSON.parse(rd.result); }catch(err){ toast("That isn't a session file."); return; }
    if(!d || !d.vdsSession || !Array.isArray(d.cols)){ toast("That isn't a session file (Save session makes one)."); return; }
    COLS = d.cols.map(c=>Object.assign(blankCol(), c, {over:c.over||{}}));
    migrateCols(d.job, d); SEL = Math.min(d.sel||0, COLS.length-1);
    if(d.wf && (!JOB || JOB.name===d.job)){ WF = d.wf; if(JOB) wfSave(); }
    render(); store.save(); toast(`Opened ${COLS.length} column${COLS.length>1?"s":""}${d.job?` for ${d.job}`:""}.${JOB && JOB.name!==d.job ? " The loaded Job JSON is a different job: load the matching one." : JOB ? "" : " Load the Job JSON for the SCID pickers."}`); };
  rd.readAsText(f); });

/* older saves: drop the Pre-1990 copy columns (one existing column per pole now) and the proposal name used as a SCID header */
let STALE = false;   // a save from before the one-column-per-pole layout (10/28/26)
function migrateCols(jobName, d){
  // old layout = a save that still has Pre-1990 copy columns. A session file written before 11/16 has no layout marker but is
  // the current layout: it must not be rebuilt (and its typed changes lost) when the Job JSON is loaded after it.
  if(d) STALE = !(d.layout>=2) && (d.cols||[]).some(c=>c && (c.twin || c.pair));
  COLS = COLS.filter(c=>!c.twin); COLS.forEach(c=>{ c.pair = false; const nm = String(c.proposal||"").trim();
    if((!nm && JOB && c.node) || jobName && nm.replace(/\s*(·\s*MR|\bMR|\((replacement|after MR)\))\s*$/i,"")===String(jobName).trim()){ const tail = (c.repl || c.after) ? " MR" : "";   /* 411: "Scid # MR" */ const s = String((JOB && c.node && JOB.nodes?.[c.node]) ? K.scid(JOB.nodes[c.node]) : (c.scid||"")).replace(/^0+(?=\d)/,""); c.proposal = s ? s + tail : tail.trim(); } });
  SEL = Math.min(SEL, COLS.length-1);
}
/* ---------- boot ---------- */
(function boot(){
  const d = store.load();
  if(d && Array.isArray(d.cols) && d.cols.length){
    COLS = d.cols.map(c=>Object.assign(blankCol(), c, {over:c.over||{}}));
    migrateCols(d.job, d);
    SEL = Math.min(d.sel||0, COLS.length-1);
  }
  render();
  setView("template");
  if(STALE && COLS.some(c=>c.node)) setTimeout(()=>toast("This saved sheet is in the old layout. Load the job JSON and it will be rebuilt with SCID headers and (replacement) columns."), 600);
})();
